import java.util.Arrays;
import java.util.Objects;

public final class BubbleSort {
    private static final int[] SAMPLE_NUMBERS = {64, 34, 25, 12, 22, 11, 90};

    private BubbleSort() {
    }

    public static void sort(int[] numbers) {
        Objects.requireNonNull(numbers, "numbers must not be null");

        for (int pass = 0; pass < numbers.length - 1; pass++) {
            boolean swapped = false;

            for (int index = 0; index < numbers.length - pass - 1; index++) {
                if (numbers[index] <= numbers[index + 1]) {
                    continue;
                }

                swap(numbers, index, index + 1);
                swapped = true;
            }

            if (!swapped) {
                break;
            }
        }
    }

    private static void swap(int[] numbers, int firstIndex, int secondIndex) {
        int temp = numbers[firstIndex];
        numbers[firstIndex] = numbers[secondIndex];
        numbers[secondIndex] = temp;
    }

    public static void main(String[] args) {
        int[] numbers = Arrays.copyOf(SAMPLE_NUMBERS, SAMPLE_NUMBERS.length);

        sort(numbers);
        System.out.println("Sorted array: ");
        System.out.println(Arrays.toString(numbers));
    }
}

